// File: .gitignore
.env
.env.local
.env.*.local
/vendor/
/node_modules/

// CORRECT.env.example exists (template, no real secrets)
// File: .env.example (tracked; used by developers to create .env locally)
DB_HOST=localhost
DB_USER=wp_user
DB_PASSWORD=CHANGE_ME_IN_LOCAL_ENV
API_KEY=your-api-key-here

// CORRECT: Load .env at runtime from gitignored .env file
// File: wp-config.php or config.php
require_once __DIR__ . '/vendor/autoload.php';
$dotenv = Dotenv\Dotenv::createImmutable( __DIR__ );
$dotenv->load();

$db_host = $_ENV['DB_HOST'] ?? 'localhost';
$db_pass = $_ENV['DB_PASSWORD'] ?? '';
$api_key = $_ENV['API_KEY'] ?? '';

// CORRECT, If .env was already committed: remove from history
// $ git rm --cached .env
// $ echo ".env" >> .gitignore
// $ git add .gitignore
// $ git commit -m "Remove tracked .env file with secrets"
// $ git push

