// CORRECT, Load secrets from environment variables via .env
// File: .env (local, gitignored)
STRIPE_SECRET_KEY=sk_live_EXAMPLE_not_a_real_key
SENDGRID_API_KEY=SG.EXAMPLE_not_a_real_key
GITHUB_TOKEN=ghp_EXAMPLE_not_a_real_key
DATABASE_PASSWORD=EXAMPLE_not_a_real_password

// File: wp-config.php or bootstrap (load .env)
require_once __DIR__ . '/vendor/autoload.php';
$dotenv = Dotenv\Dotenv::createImmutable( __DIR__ );
$dotenv->load();

// CORRECT: Read secrets from environment
// File: src/Services/PaymentGateway.php
class PaymentGateway {
    public function chargeCard( $amount ) {
        // Load secret at runtime from environment, never hardcoded
        $stripe_key = $_ENV['STRIPE_SECRET_KEY'] ?? '';
        if ( empty( $stripe_key ) ) {
            throw new \Exception( 'STRIPE_SECRET_KEY not set in environment' );
        }
        $stripe = new \Stripe\StripeClient( $stripe_key );
        return $stripe->charges->create( [
            'amount' => $amount,
            'currency' => 'usd',
        ] );
    }
}

// CORRECT: OAuth token from environment
// File: src/ExternalAPI.php
$oauth_token = $_ENV['GITHUB_TOKEN'] ?? '';
if ( empty( $oauth_token ) ) {
    throw new \Exception( 'GITHUB_TOKEN not set' );
}
$headers = [ 'Authorization' => "Bearer {$oauth_token}" ];
$response = wp_remote_get( 'https://api.github.com/user', compact( 'headers' ) );

